version.transform:
(
  $data := $ 
    ~> | $ | {
      "category": $moment(creditedAt).format("MM/DD/YYYY")
    } |;

  $groupedData := ($data{
    category: {
      "category": $first(category),
      "utilization": $sum(utilizationTime[$not($isNil($))]) / 3600
    }
  } ~> $values)^(category);

  $avg := $round($average($groupedData.utilization), 1);

  {
    "categories": [
        {
            "category": [$groupedData.{
              "label": category
            }]
        }
    ],
    "dataSet": [
        {
            "data": [$groupedData.{
              "value": utilization
            }]
        }
    ],
    "trendlines": [
      {
        "line": [
          {
            "startvalue": 20.4,
            "color": "#43a047",
            "displayvalue": "85%",
            "valueOnRight": true
          },
          {
            "startvalue": 21.6,
            "color": "#ffa000",
            "displayvalue": "90%",
            "valueOnRight": true
          },
          {
            "startvalue": 24,
            "color": "#f44336",
            "displayvalue": "100%",
            "valueOnRight": true
          },
          {
            "startvalue": $avg,
            "color": "#006fba",
            "displayvalue": "Avg: " & $string($avg),
            "valueOnRight": true
          }
        ]
      }
    ]
  }
)
